        for c in range(w):
            color = grid[r][c]
            if color in structural or seen[r][c]:
                continue
            q = [(r, c)]
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
