                    if (0 <= ny < h and 0 <= nx < w and not seen_panel[ny][nx]
                            and grid[ny][nx] == panel_color):
                        seen_panel[ny][nx] = True
                        q.append((ny, nx))
            panels.append((min(y for y, _ in cells), max(y for y, _ in cells),
                           min(x for _, x in cells), max(x for _, x in cells)))

    for obj in objects:
        containing = [p for p in panels
                      if p[0] <= obj["top"] and p[1] >= obj["bottom"]
                      and p[2] <= obj["left"] and p[3] >= obj["right"]]
        if containing:
            obj["panel"] = min(containing, key=lambda p: (p[1]-p[0]+1)*(p[3]-p[2]+1))
        else:
            obj["panel"] = (obj["top"], obj["bottom"], obj["left"], obj["right"])

    # Adjacent objects in a shared row or column are consecutive along that line.
    adjacent = set()
    for i, a in enumerate(objects):
        for j, b in enumerate(objects):
            if i == j:
                continue
            if a["top"] == b["top"]:
                line = sorted((k for k, o in enumerate(objects) if o["top"] == a["top"]),
                              key=lambda k: objects[k]["left"])
                if abs(line.index(i) - line.index(j)) == 1:
                    adjacent.add((i, j))
            if a["left"] == b["left"]:
                line = sorted((k for k, o in enumerate(objects) if o["left"] == a["left"]),
                              key=lambda k: objects[k]["top"])
                if abs(line.index(i) - line.index(j)) == 1:
                    adjacent.add((i, j))

    candidates = [[i for i, obj in enumerate(objects) if obj["color"] == color]
                  for color in sequence]

    # Match the key sequence to a non-repeating path through the objects.
    path = []

    def search(pos, used):
        if pos == len(sequence):
            return True
        for i in candidates[pos]:
            if i in used:
                continue
            if pos and (path[-1], i) not in adjacent:
                continue
            path.append(i)
            used.add(i)
            if search(pos + 1, used):
                return True
            used.remove(i)
            path.pop()
        return False

    if not candidates or not search(0, set()):
        return out

    # Connect each object to the next, extending the source object's color
    # through the gap between their panels.
    for a_idx, b_idx in zip(path, path[1:]):
        a, b = objects[a_idx], objects[b_idx]
        ap, bp = a["panel"], b["panel"]
        color = a["color"]

        if a["top"] == b["top"]:
            rows = range(a["top"], a["bottom"] + 1)
            if ap[2] < bp[2]:
                cols = range(ap[3] + 1, bp[2])
            else:
                cols = range(bp[3] + 1, ap[2])
            for r in rows:
                for c in cols:
                    out[r][c] = color
        elif a["left"] == b["left"]:
